function pos_ticket_v141(App $app,array $tenant,array $user,int $ticketId=0,string $type='catalog',?int $tableId=null):array {
 $b=pos_access_148($app,$user,$tenant);return pos_ticket_get_148($app,$tenant,$b,$ticketId?:pos_open_148($app,$tenant,$user,$b,$type,$tableId));
}

function pos_recalculate_v141(App $app,int $ticketId):array {return pos_recalculate_148($app,$ticketId);}

function pos_items_v141(App $app,int $ticketId):array{return $app->all('SELECT i.*,p.image,p.sku FROM pos_ticket_items i LEFT JOIN products p ON p.id=i.product_id WHERE i.ticket_id=? ORDER BY i.id',[$ticketId]);}

function pos_product_options_v141(App $app,int $tenantId,int $productId,array $selected):array
{
    $groups=$app->all('SELECT id,name,type,is_required,min_select,max_select FROM product_option_groups WHERE tenant_id=? AND product_id=? AND is_active=1 ORDER BY sort_order,id',[$tenantId,$productId]);$rows=[];
    if($selected){$marks=implode(',',array_fill(0,count($selected),'?'));$params=array_merge([$tenantId,$productId],$selected);$rows=$app->all('SELECT po.id,po.group_id,po.name,po.price_delta,pog.name group_name FROM product_options po JOIN product_option_groups pog ON pog.id=po.group_id WHERE pog.tenant_id=? AND pog.product_id=? AND po.is_active=1 AND po.id IN ('.$marks.') ORDER BY pog.sort_order,po.sort_order',$params);if(count($rows)!==count($selected))throw new RuntimeException('Una opción seleccionada no pertenece a este producto.');}
    $counts=[];foreach($rows as $row)$counts[(int)$row['group_id']]=($counts[(int)$row['group_id']]??0)+1;foreach($groups as $group){$count=$counts[(int)$group['id']]??0;$minimum=(int)$group['is_required']?max(1,(int)$group['min_select']):(int)$group['min_select'];$maximum=max($minimum,(int)$group['max_select']);if($group['type']==='single')$maximum=1;if($count<$minimum||$count>$maximum)throw new RuntimeException('Revisa las opciones de '.$group['name'].': selecciona de '.$minimum.' a '.$maximum.'.');}
    $price=0.0;$labels=[];foreach($rows as $row){$price+=(float)$row['price_delta'];$labels[]=$row['group_name'].': '.$row['name'];}return ['price'=>$price,'json'=>$rows?json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null,'label'=>implode(' · ',$labels)];
}

function pos_handle_action_v141(App $app,array $user,array $tenant,array $ticket):void {
 if(is_post())pos_edit_148($app,$tenant,$user,pos_access_148($app,$user,$tenant),(int)$ticket['id']);
}

function pos_catalog_products_v141(App $app,array $tenant,array $branch):array
{
    $q=trim((string)($_GET['q']??''));$category=(int)($_GET['category']??0);$params=[$branch['id'],$tenant['id']];$where='p.tenant_id=? AND p.status="active"';if($q!==''){$where.=' AND (p.name LIKE ? OR p.sku LIKE ? OR p.description LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($category){$where.=' AND p.category_id=?';$params[]=$category;}return $app->all('SELECT p.*,COALESCE(i.quantity,0) stock FROM products p LEFT JOIN product_inventory i ON i.product_id=p.id AND i.branch_id=? WHERE '.$where.' ORDER BY p.name LIMIT 80',$params);
}

function pos_order_screen_v141(App $app,array $user,array $tenant,array $ticket):void {pos_workspace_148($app,$user,$tenant,(int)$ticket['id']);}

function pos_checkout_v141(App $app,array $user,array $tenant,array $ticket):void {pos_collect_148($app,$user,$tenant,[(int)$ticket['id']]);}

function tenant_sales_v141(App $app,array $user,array $tenant):void {pos_launch_148($app,$user,$tenant);}

function tenant_customers_v141(App $app,array $user,array $tenant):void
{
    if(is_post()){verify_csrf();try{$action=(string)($_POST['action']??'save');$customerId=(int)($_POST['customer_id']??0);if($action==='credit'){if(!in_array($user['role'],['tenant_admin','manager'],true))throw new RuntimeException('Solo el dueño o un gestor puede autorizar crédito.');if(!$app->one('SELECT 1 FROM tenant_customers WHERE tenant_id=? AND user_id=?',[$tenant['id'],$customerId]))throw new RuntimeException('Cliente no asociado a esta tienda.');$limit=max(0,(float)($_POST['credit_limit']??0));$enabled=isset($_POST['credit_enabled'])?1:0;$terms=max(1,(int)($_POST['payment_terms_days']??30));$app->exec('INSERT INTO customer_credit_profiles(tenant_id,user_id,credit_enabled,credit_limit,payment_terms_days) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE credit_enabled=VALUES(credit_enabled),credit_limit=VALUES(credit_limit),payment_terms_days=VALUES(payment_terms_days)',[$tenant['id'],$customerId,$enabled,$limit,$terms]);flash('success','Condiciones de crédito actualizadas.');}else{$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=trim((string)($_POST['phone']??''));$idNumber=trim((string)($_POST['id_number']??''));if($name===''||$phone==='')throw new RuntimeException('Nombre y teléfono son obligatorios.');$customer=$email!==''?$app->one('SELECT * FROM users WHERE email=?',[$email]):null;if($customer&&$customer['role']!=='customer')throw new RuntimeException('Ese correo pertenece a un usuario administrativo.');if(!$customer){if($email===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$email='cliente-'.bin2hex(random_bytes(5)).'@registro.fisitaap.local';$password=bin2hex(random_bytes(12));$app->exec('INSERT INTO users(tenant_id,name,email,phone,password_hash,role,is_active,email_verified_at) VALUES(NULL,?,?,?,?,"customer",1,NOW())',[$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$customerId=(int)$app->db->lastInsertId();}else{$customerId=(int)$customer['id'];if(!$app->one('SELECT 1 FROM tenant_customers WHERE tenant_id=? AND user_id=?',[$tenant['id'],$customerId]))throw new RuntimeException('Ese correo ya pertenece a un cliente de otra tienda. Pídele al cliente que actualice sus datos desde su propia cuenta.');}$app->exec('INSERT IGNORE INTO tenant_customers(tenant_id,user_id) VALUES(?,?)',[$tenant['id'],$customerId]);$app->exec('INSERT INTO customer_credit_profiles(tenant_id,user_id,notes) VALUES(?,?,?) ON DUPLICATE KEY UPDATE notes=IF(VALUES(notes)!="",VALUES(notes),notes)',[$tenant['id'],$customerId,$idNumber!==''?'Identificación: '.$idNumber:'']);flash('success','Cliente guardado y disponible para facturación.');}}catch(Throwable $e){flash('error',$e->getMessage());}redirect(url('admin/clientes'));}
    $rows=$app->all('SELECT u.id,u.name,u.email,u.phone,COALESCE(cp.credit_enabled,0) credit_enabled,COALESCE(cp.credit_limit,0) credit_limit,COALESCE(cp.current_balance,0) current_balance,COALESCE(cp.payment_terms_days,30) payment_terms_days,COUNT(DISTINCT o.id) orders_count,COALESCE(SUM(CASE WHEN o.status!="cancelled" THEN o.total ELSE 0 END),0) spent FROM tenant_customers tc JOIN users u ON u.id=tc.user_id LEFT JOIN customer_credit_profiles cp ON cp.tenant_id=tc.tenant_id AND cp.user_id=tc.user_id LEFT JOIN orders o ON o.tenant_id=tc.tenant_id AND o.user_id=tc.user_id WHERE tc.tenant_id=? GROUP BY u.id ORDER BY u.name',[$tenant['id']]);admin_shell_start('Clientes y crédito',$user,$tenant,'clientes');echo '<div class="split"><form class="card admin-card" method="post">'.csrf_field().'<input type="hidden" name="action" value="save"><h2>Registrar cliente</h2>'.field('Nombre completo','name','',true).field('Identificación','id_number','').'<div class="split">'.field('Teléfono','phone','',true).field('Correo','email','',false,'email').'</div><button class="btn btn-block">Guardar cliente</button></form><section class="card admin-card"><h2>Clientes de la tienda</h2><div class="table-wrap"><table class="table"><tr><th>Cliente</th><th>Compras</th><th>Crédito</th><th>Configurar crédito</th></tr>';foreach($rows as $row)echo '<tr><td><strong>'.e($row['name']).'</strong><br><small>'.e($row['phone'].' · '.$row['email']).'</small></td><td>'.(int)$row['orders_count'].'<br>'.money((float)$row['spent']).'</td><td>'.($row['credit_enabled']?'Disponible '.money(max(0,(float)$row['credit_limit']-(float)$row['current_balance'])):'No habilitado').'<br><small>Saldo '.money((float)$row['current_balance']).'</small></td><td><form method="post" class="credit-inline">'.csrf_field().'<input type="hidden" name="action" value="credit"><input type="hidden" name="customer_id" value="'.(int)$row['id'].'"><label><input type="checkbox" name="credit_enabled" '.($row['credit_enabled']?'checked':'').'> Autorizar</label><input class="input compact" type="number" step="0.01" name="credit_limit" value="'.e($row['credit_limit']).'" placeholder="Límite"><input class="input compact" type="number" name="payment_terms_days" value="'.(int)$row['payment_terms_days'].'" placeholder="Días"><input type="hidden" name="notes" value=""><button class="btn btn-light">Guardar</button></form></td></tr>';if(!$rows)echo '<tr><td colspan="4">Registra el primer cliente para facturar.</td></tr>';echo '</table></div></section></div>';admin_shell_end();
}

function pos_options_api_v142(App $app):never
{
    $user=current_user();if(!$user||!in_array($user['role'],['tenant_admin','manager','cashier'],true))json_response(['ok'=>false,'error'=>'Acceso de caja requerido.'],403);$productId=(int)($_GET['product_id']??0);$product=$app->one('SELECT id,name FROM products WHERE id=? AND tenant_id=? AND status="active"',[$productId,$user['tenant_id']]);if(!$product)json_response(['ok'=>false,'error'=>'Producto no disponible.'],404);$groups=$app->all('SELECT id,name,type,is_required,min_select,max_select FROM product_option_groups WHERE tenant_id=? AND product_id=? AND is_active=1 ORDER BY sort_order,id',[$user['tenant_id'],$productId]);foreach($groups as &$group)$group['options']=$app->all('SELECT id,name,price_delta FROM product_options WHERE group_id=? AND is_active=1 ORDER BY sort_order,id',[$group['id']]);unset($group);json_response(['ok'=>true,'product'=>$product,'groups'=>$groups]);
}

function tenant_kitchen_v142(App $app,array $user,array $tenant):void
{
    if(is_post()&&($_POST['action']??'')==='pos_served'){
        verify_csrf();$id=(int)($_POST['ticket_id']??0);
        $app->exec('UPDATE pos_ticket_items i JOIN pos_tickets t ON t.id=i.ticket_id SET i.kitchen_status="served" WHERE t.id=? AND t.tenant_id=? AND i.kitchen_status="ready"',[$id,$tenant['id']]);
        audit($app,(int)$tenant['id'],(int)$user['id'],'kitchen_dispatch','pos_ticket',$id);redirect(url('admin/cocina'));
    }
    if(is_post()&&str_starts_with((string)($_POST['action']??''),'pos_')){verify_csrf();$ticketId=(int)($_POST['ticket_id']??0);$action=(string)$_POST['action'];$app->db->beginTransaction();try{$ticket=$app->one('SELECT * FROM pos_tickets WHERE id=? AND tenant_id=? AND status<>"void" FOR UPDATE',[$ticketId,$tenant['id']]);if(!$ticket)throw new RuntimeException('La comanda ya no está disponible.');if($action==='pos_prepare')$app->exec('UPDATE pos_ticket_items SET kitchen_status="preparing" WHERE ticket_id=? AND kitchen_status="sent"',[$ticketId]);elseif($action==='pos_ready'){$app->exec('UPDATE pos_ticket_items SET kitchen_status="ready" WHERE ticket_id=? AND kitchen_status IN ("sent","preparing")',[$ticketId]);$app->exec('UPDATE pos_tickets SET fulfillment_state=IF(sale_type="express" AND fulfillment_state IN ("pending","preparing"),"ready",fulfillment_state) WHERE id=?',[$ticketId]);}else throw new RuntimeException('Acción de cocina inválida.');$app->db->commit();flash('success','Comanda '.$ticket['ticket_number'].' actualizada.');}catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('admin/cocina'));}
    if(is_post()){verify_csrf();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'');$transitions=['confirm'=>['new','confirmed'],'prepare'=>['confirmed','preparing'],'ready'=>['preparing','ready'],'pickup_delivered'=>['ready','delivered']];if($id&&isset($transitions[$action])){[$from,$to]=$transitions[$action];$order=$app->one('SELECT id,order_number,status,delivery_type FROM orders WHERE id=? AND tenant_id=?',[$id,$tenant['id']]);$pickupAllowed=$action!=='pickup_delivered'||($order&&$order['delivery_type']==='pickup');if($order&&$order['status']===$from&&$pickupAllowed){$app->exec('UPDATE orders SET status=? WHERE id=? AND tenant_id=? AND status=?',[$to,$id,$tenant['id'],$from]);audit($app,$tenant['id'],$user['id'],'kitchen_'.$action,'order',$id);flash('success','Pedido #'.$order['order_number'].' actualizado.');}else flash('error','El pedido cambió de estado.');}redirect(url('admin/cocina'));}
    $online=$app->all("SELECT *,TIMESTAMPDIFF(MINUTE,created_at,NOW()) age_minutes FROM orders WHERE tenant_id=? AND status IN ('new','confirmed','preparing','ready') ORDER BY FIELD(status,'new','confirmed','preparing','ready'),created_at ASC LIMIT 80",[$tenant['id']]);$pos=$app->all("SELECT pt.*,rt.name table_name,TIMESTAMPDIFF(MINUTE,pt.created_at,NOW()) age_minutes FROM pos_tickets pt LEFT JOIN restaurant_tables rt ON rt.id=pt.table_id WHERE pt.tenant_id=? AND pt.status NOT IN ('void','suspended') AND EXISTS(SELECT 1 FROM pos_ticket_items pi WHERE pi.ticket_id=pt.id AND pi.kitchen_status IN ('sent','preparing','ready')) ORDER BY pt.created_at",[$tenant['id']]);admin_shell_start(($tenant['catalog_label']??'Catálogo')==='Menú'?'Vista cocina':'Vista monitor',$user,$tenant,'cocina');echo '<div class="ops-head" data-auto-refresh="30000"><p class="muted">Pedidos web y comandas de mesas, venta rápida y express.</p><span class="live-indicator">Actualización automática cada 30 s</span></div><div class="ops-grid">';
    foreach($pos as $ticket){$items=$app->all('SELECT product_name,quantity,options_json,notes,kitchen_status FROM pos_ticket_items WHERE ticket_id=? AND kitchen_status IN ("sent","preparing","ready") ORDER BY id',[$ticket['id']]);$states=array_unique(array_column($items,'kitchen_status'));$state=in_array('preparing',$states,true)?'Preparando':(in_array('sent',$states,true)?'Nueva comanda':'Lista');echo '<article class="card ops-card"><div class="ops-card-head"><div><span class="tag">'.e($state).'</span><h2>'.e(($ticket['table_name']?:($ticket['sale_type']==='express'?'Express':'Venta rápida')).(!empty($ticket['display_label'])?' · '.$ticket['display_label']:'')).'</h2><small>'.e($ticket['ticket_number']).'</small></div><span class="ops-time">'.(int)$ticket['age_minutes'].' min</span></div><ul class="ops-items">';foreach($items as $item){$details=[];foreach(json_decode((string)$item['options_json'],true)?:[] as $option)$details[]=($option['group_name']??$option['group']??'Opción').': '.($option['name']??'');echo '<li><div><strong>'.e($item['product_name']).'</strong>'.($details?'<small>'.e(implode(' · ',$details)).'</small>':'').($item['notes']?'<small>Nota: '.e($item['notes']).'</small>':'').'</div><span>'.e($item['quantity']).'</span></li>';}echo '</ul><div class="ops-actions"><form method="post">'.csrf_field().'<input type="hidden" name="ticket_id" value="'.(int)$ticket['id'].'">';if($state==='Nueva comanda')echo '<button class="btn btn-accent" name="action" value="pos_prepare">Iniciar preparación</button>';elseif($state==='Preparando')echo '<button class="btn btn-accent" name="action" value="pos_ready">Marcar lista</button>';else echo '<button class="btn btn-light" name="action" value="pos_served">Retirar de cocina / despachar</button>';echo '</form>'.(role_can($user['role'],'recibo')?'<a class="btn btn-light" href="'.url('admin/recibo?comanda='.(int)$ticket['id']).'">Comandas Print</a>':'').'</div></article>';}
    $labels=['new'=>'Nuevo','confirmed'=>'Confirmado','preparing'=>'Preparando','ready'=>'Listo'];$next=['new'=>['confirm','Aceptar pedido'],'confirmed'=>['prepare','Iniciar preparación'],'preparing'=>['ready','Marcar como listo']];foreach($online as $order){$items=$app->all('SELECT product_name,quantity,unit_label,options_json,notes FROM order_items WHERE order_id=? ORDER BY id',[$order['id']]);echo '<article class="card ops-card"><div class="ops-card-head"><div><span class="tag">'.e($labels[$order['status']]??$order['status']).'</span><h2>Pedido web #'.e($order['order_number']).'</h2><small>'.e($order['customer_name']).'</small></div><span class="ops-time">'.(int)$order['age_minutes'].' min</span></div><ul class="ops-items">';foreach($items as $item)echo '<li><div><strong>'.e($item['product_name']).'</strong>'.order_item_details_html($item).'</div><span>'.e($item['quantity']).' '.e($item['unit_label']).'</span></li>';echo '</ul>'.(!empty($order['notes'])?'<p class="ops-notes">'.nl2br(e($order['notes'])).'</p>':'').'<div class="ops-actions"><a class="btn btn-light" href="'.url('admin/pedidos?view='.(int)$order['id']).'">Ver detalle</a>';if(isset($next[$order['status']])){[$action,$label]=$next[$order['status']];echo '<form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$order['id'].'"><button class="btn btn-accent" name="action" value="'.e($action).'">'.e($label).'</button></form>';}elseif($order['status']==='ready'&&$order['delivery_type']==='pickup')echo '<form method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$order['id'].'"><button class="btn btn-accent" name="action" value="pickup_delivered">Entregado en local</button></form>';else echo '<span class="status">Esperando entrega</span>';echo '</div></article>';}
    if(!$pos&&!$online)echo '<div class="card empty">No hay pedidos pendientes.</div>';echo '</div>';admin_shell_end();
}

function tenant_shifts_v142(App $app,array $user,array $tenant):void
{
    $branch=physical_branch_v14($app,$tenant);if(is_post()){verify_csrf();try{$action=(string)($_POST['action']??'open');if($action==='open'){$open=$app->one('SELECT id FROM pos_shifts WHERE tenant_id=? AND branch_id=? AND user_id=? AND status="open"',[$tenant['id'],$branch['id'],$user['id']]);if($open)throw new RuntimeException('Ya tienes un turno abierto.');$app->exec('INSERT INTO pos_shifts(tenant_id,branch_id,user_id,name,opening_cash,status,opened_at) VALUES(?,?,?,?,?,"open",NOW())',[$tenant['id'],$branch['id'],$user['id'],trim((string)($_POST['name']??'Turno')),max(0,(float)($_POST['opening_cash']??0))]);}else{$id=(int)($_POST['id']??0);$app->db->beginTransaction();$shift=$app->one('SELECT * FROM pos_shifts WHERE id=? AND tenant_id=? AND status="open" FOR UPDATE',[$id,$tenant['id']]);if(!$shift)throw new RuntimeException('Turno no disponible.');$cash=(float)($app->one('SELECT COALESCE(SUM(pp.amount),0) total FROM pos_payments pp JOIN sales s ON s.id=pp.sale_id WHERE s.shift_id=? AND pp.payment_method="Efectivo"',[$id])['total']??0);$expected=(float)$shift['opening_cash']+$cash;$closing=(float)($_POST['closing_cash']??0);$app->exec('UPDATE pos_shifts SET closing_cash=?,expected_cash=?,difference_amount=?,notes=?,status="closed",closed_at=NOW() WHERE id=?',[$closing,$expected,$closing-$expected,trim((string)($_POST['notes']??'')),$id]);$app->db->commit();}flash('success','Turno actualizado.');}catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('admin/turnos'));}$rows=$app->all('SELECT s.*,u.name user_name,(SELECT COALESCE(SUM(pp.amount),0) FROM pos_payments pp JOIN sales v ON v.id=pp.sale_id WHERE v.shift_id=s.id AND pp.payment_method="Efectivo") cash_sales FROM pos_shifts s JOIN users u ON u.id=s.user_id WHERE s.tenant_id=? ORDER BY s.opened_at DESC LIMIT 100',[$tenant['id']]);admin_shell_start('Turnos y cierres de caja',$user,$tenant,'turnos');echo '<div class="split"><form class="card admin-card" method="post">'.csrf_field().'<input type="hidden" name="action" value="open"><h2>Abrir turno</h2>'.field('Nombre','name','Turno '.date('d/m H:i'),true).field('Fondo inicial','opening_cash',0,true,'number','0.01').'<button class="btn btn-block">Abrir caja</button></form><section class="card admin-card"><h2>Historial</h2><div class="table-wrap"><table class="table"><tr><th>Usuario</th><th>Apertura</th><th>Efectivo vendido</th><th>Estado</th><th>Cierre</th><th></th></tr>';foreach($rows as $row){echo '<tr><td>'.e($row['user_name']).'</td><td>'.e(date('d/m/Y H:i',strtotime($row['opened_at']))).'</td><td>'.money((float)$row['cash_sales']).'</td><td>'.e($row['status']).'</td><td>'.($row['closed_at']?money((float)$row['closing_cash']).'<br><small>Diferencia '.money((float)$row['difference_amount']).'</small>':'—').'</td><td>';if($row['status']==='open')echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="close"><input type="hidden" name="id" value="'.(int)$row['id'].'"><input class="input compact" type="number" step="0.01" name="closing_cash" placeholder="Efectivo contado" required><input class="input compact" name="notes" placeholder="Observación"><button class="btn">Cerrar</button></form>';echo '</td></tr>';}echo '</table></div></section></div>';admin_shell_end();
}

function tenant_printer_v142(App $app,array $user,array $tenant):void
{
    $branch=physical_branch_v14($app,$tenant);if(!$branch)throw new RuntimeException('No hay una sucursal activa.');
    $points=['receipt'=>'Caja / recibo','kitchen'=>'Cocina','bar'=>'Barra','dispatch'=>'Despacho','copy'=>'Copia'];if(function_exists('r3_active')&&r3_active($app)){$points=r3_print_points($app,$tenant);if(is_post()&&($_POST['action']??'')==='add_zone')r3_print_zone_save($app,$tenant);}
    if(is_post()){verify_csrf();try{
        $posted=is_array($_POST['printer']??null)?$_POST['printer']:[];$normalized=[];
        foreach($points as $point=>$unused){$row=is_array($posted[$point]??null)?$posted[$point]:[];$type=in_array((string)($row['type']??''),['browser','network','usb','bluetooth'],true)?(string)$row['type']:'browser';$width=in_array((string)($row['width']??''),['58','80'],true)?(string)$row['width']:'80';$normalized[$point]=['width'=>$width,'type'=>$type,'name'=>mb_substr(trim((string)($row['name']??'')),0,150),'host'=>mb_substr(trim((string)($row['host']??'')),0,150),'port'=>max(1,min(65535,(int)($row['port']??9100))),'autoprint'=>isset($row['autoprint'])?1:0];}
        $receipt=$normalized['receipt'];$token=mb_substr(trim((string)($_POST['receipt_bridge_token']??($branch['receipt_bridge_token']??''))),0,128);$json=json_encode($normalized,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$app->exec('UPDATE branches SET receipt_width=?,receipt_printer_type=?,receipt_printer_name=?,receipt_printer_host=?,receipt_printer_port=?,receipt_autoprint=?,receipt_bridge_token=?,printer_points_json=? WHERE id=? AND tenant_id=?',[$receipt['width'],$receipt['type'],$receipt['name'],$receipt['host'],$receipt['port'],$receipt['autoprint'],$token,$json,$branch['id'],$tenant['id']]);flash('success','Impresoras por punto guardadas para '.($branch['name']??'la sucursal').'.');redirect(url('admin/impresion?branch_id='.(int)$branch['id']));
    }catch(Throwable $e){flash('error',$e->getMessage());}}
    $profiles=printer_profiles_148($branch);$branches=$app->all('SELECT id,name FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,name',[$tenant['id']]);admin_shell_start('Impresoras y recibos',$user,$tenant,'impresion');echo '<section class="card admin-card"><h2>Impresoras por punto · '.e($branch['name']).'</h2><p class="muted">Asigna una impresora diferente a cada punto de trabajo. La categoría define el destino de la comanda y FISITAAP Print usa el perfil correspondiente. En Windows selecciona el nombre exacto de la impresora instalada para cada zona. También puedes generar PDF o usar una impresora de red; el papel puede ser de 58 u 80 mm.</p>';if(count($branches)>1){echo '<label class="form-group"><span>Sucursal</span><select class="input" onchange="if(this.value)location.href=\''.e(url('admin/impresion')).'?branch_id=\'+this.value"><option value="">'.e($branch['name']).'</option>';foreach($branches as $b)if((int)$b['id']!==(int)$branch['id'])echo '<option value="'.(int)$b['id'].'">'.e($b['name']).'</option>';echo '</select></label>';}echo '<form method="post">'.csrf_field().pos_hidden_148('branch_id',$branch['id']).field('Token de FISITAAP Print','receipt_bridge_token',$branch['receipt_bridge_token']??'',false,'password').'<div class="grid grid-2">';foreach($points as $point=>$label){$p=$profiles[$point]??printer_profile_148($branch,$point);echo '<section class="card printer-point"><h3>'.e($label).'</h3><p class="muted">Destino <code>'.e($point).'</code></p><label>Tipo de conexión<select class="input" name="printer['.e($point).'][type]"><option value="browser" '.($p['type']==='browser'?'selected':'').'>FISITAAP Print · PDF</option><option value="network" '.($p['type']==='network'?'selected':'').'>Red / IP</option><option value="usb" '.($p['type']==='usb'?'selected':'').'>USB</option><option value="bluetooth" '.($p['type']==='bluetooth'?'selected':'').'>Bluetooth</option></select></label><label>Ancho del papel<select class="input" name="printer['.e($point).'][width]"><option value="58" '.($p['width']===58?'selected':'').'>58 mm</option><option value="80" '.($p['width']===80?'selected':'').'>80 mm</option></select></label><label>Nombre exacto en Windows<input class="input" name="printer['.e($point).'][name]" value="'.e($p['name']).'" maxlength="150" placeholder="Ej.: EPSON TM-T20III"></label><div class="grid grid-2"><label>IP o host<input class="input" name="printer['.e($point).'][host]" value="'.e($p['host']).'" maxlength="150" placeholder="Solo red"></label><label>Puerto ESC/POS<input class="input" type="number" name="printer['.e($point).'][port]" value="'.(int)$p['port'].'" min="1" max="65535"></label></div><label class="check"><input type="checkbox" name="printer['.e($point).'][autoprint]" '.($p['autoprint']?'checked':'').'> Imprimir automáticamente</label></section>';}echo '</div><p><button class="btn btn-accent">Guardar todos los puntos</button> <a class="btn btn-light" target="_blank" href="'.url('admin/recibo?demo=1&auto=1').'">Probar recibo en PDF</a> <a class="btn btn-light" target="_blank" href="'.url('admin/recibo?prueba_comanda=1&auto=1').'">Probar comandas por punto</a></p></form></section><section class="card admin-card"><h3>Cómo funciona</h3><p>Recibo y cobro usan <strong>Caja</strong>. Cada categoría envía sus productos a <strong>Cocina</strong>, <strong>Barra</strong>, <strong>Despacho</strong> o <strong>Copia</strong>. La misma asignación se aplica a ventas web, Express, venta rápida y mesas. Si una impresora no está disponible, el PDF y la impresión del navegador siguen disponibles.</p></section>';if(function_exists('r3_active')&&r3_active($app))echo '<section class="card admin-card"><h2>Crear zona de impresión</h2><form method="post">'.csrf_field().pos_hidden_148('action','add_zone').field('Nombre de la zona (ej.: Parrilla, repostería, caja 2)','zone_name','',true).'<button class="btn">Crear zona</button></form></section>';admin_shell_end();
}

function tenant_receipt_v142(App $app,array $user,array $tenant):void
{
    if(isset($_GET['comanda'])||isset($_GET['pedido'])||isset($_GET['prueba_comanda'])){tenant_comanda_qa($app,$user,$tenant);return;}
    $reprint=false;if(is_post()&&($_POST['action']??'')==='reprint'){verify_csrf();$reprint=true;$_GET['auto']=1;}
    $id=(int)($_GET['venta']??0);$sale=$id?$app->one('SELECT s.*,b.name branch_name,b.receipt_width,b.receipt_autoprint,b.receipt_bridge_token,t.name tenant_name FROM sales s JOIN branches b ON b.id=s.branch_id JOIN tenants t ON t.id=s.tenant_id WHERE s.id=? AND s.tenant_id=?',[$id,$tenant['id']]):null;$branch=$sale?:physical_branch_v14($app,$tenant);$width=(($branch['receipt_width']??'80')==='58'?'58mm':'80mm');$items=$sale?$app->all('SELECT * FROM sale_items WHERE sale_id=? ORDER BY id',[$id]):[];$lines=[];$lines[]=$sale['tenant_name']??$tenant['name'];$lines[]=$sale['branch_name']??($branch['name']??'Sucursal');$lines[]='--------------------------------';if($sale){$lines[]='Venta '.$sale['sale_number'];$lines[]=date('d/m/Y H:i',strtotime($sale['created_at']));foreach($items as $item){$lines[]=$item['quantity'].' x '.$item['product_name'].'  '.money((float)$item['line_subtotal']+(float)$item['line_tax']);foreach(json_decode((string)($item['options_json']??''),true)?:[] as $option)$lines[]='  '.($option['group_name']??$option['group']??'').': '.$option['name'];if(!empty($item['notes']))$lines[]='  Nota: '.$item['notes'];}$lines[]='--------------------------------';$lines[]='Subtotal '.money((float)$sale['subtotal']);$lines[]='Impuestos '.money((float)$sale['tax_total']);$lines[]='Servicio '.money((float)($sale['service_total']??0));$lines[]='Descuento '.money((float)$sale['discount_total']);$lines[]='TOTAL '.money((float)$sale['total']);$lines[]='Cliente: '.$sale['customer_name'];$lines[]=$sale['notes'];foreach($app->all('SELECT payment_method,SUM(amount) amount FROM pos_payments WHERE sale_id=? GROUP BY payment_method',[$sale['id']]) as $pay)$lines[]=$pay['payment_method'].' '.money((float)$pay['amount']);if((float)$sale['change_due']>0)$lines[]='VUELTO '.money((float)$sale['change_due']);}else{$lines[]='PRUEBA DE IMPRESION';$lines[]='1 x Producto de ejemplo  '.money(2500);$lines[]='--------------------------------';$lines[]='TOTAL '.money(2500);}$lines[]='Gracias por su compra';$payload=['id'=>$sale?'tenant-'.$tenant['id'].'-receipt-'.$sale['id']:'test-'.bin2hex(random_bytes(12)),'document'=>'receipt','width'=>(int)($branch['receipt_width']??80),'text'=>implode("\n",$lines)."\n\n"];
    if(function_exists('r3_active')&&r3_active($app)){$fullBranch=$app->one('SELECT * FROM branches WHERE id=? AND tenant_id=?',[$sale['branch_id']??$branch['id'],$tenant['id']]);if($fullBranch){$payload['printer']=printer_profile_148($fullBranch);$payload['width']=$payload['printer']['width'];}}
    $payload['id'].=$reprint?'-reprint-'.bin2hex(random_bytes(8)):'';if($reprint&&$sale)audit($app,(int)$tenant['id'],(int)$user['id'],'receipt_reprint','sale',(int)$sale['id']);$payloadJson=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT);admin_shell_start('Recibo térmico',$user,$tenant,'impresion');echo '<section class="card admin-card print-result-card"><div class="receipt-preview" style="--receipt-width:'.e($width).'" id="thermalReceipt">';foreach($lines as $line)echo '<div>'.e($line).'</div>';echo '</div><div class="alert" data-print-status>Recibo preparado. Comprobando el puente de impresión…</div><form method="post">'.csrf_field().'<button class="btn btn-light" name="action" value="reprint">Reimprimir recibo</button></form><p><button class="btn" type="button" data-bridge-print>Imprimir con Print Bridge</button> <button class="btn btn-light" type="button" onclick="window.print()">Imprimir desde navegador</button> <a class="btn btn-light" href="'.url(!empty($_GET['volver_ticket'])?'admin/ventas?screen=checkout&ticket='.(int)$_GET['volver_ticket']:'admin/ventas').'">Continuar</a></p><script type="application/json" id="fisitaapPrintPayload">'.$payloadJson.'</script><div data-print-job data-token="'.e((string)($branch['receipt_bridge_token']??'')).'" data-auto="'.((!empty($_GET['auto'])&&((function_exists('r3_active')&&r3_active($app))||$reprint||!empty($_GET['demo'])||!empty($branch['receipt_autoprint'])))?'1':'0').'"></div></section>';if($sale&&!$reprint)pos_charge_comandas_148($app,$tenant,$sale);admin_shell_end();
}

function tenant_comanda_qa(App $app,array $user,array $tenant):void
{
    $copy=false;if(is_post()&&($_POST['action']??'')==='reprint_comanda'){verify_csrf();$copy=true;$_GET['auto']=1;}
    $test=!empty($_GET['prueba_comanda']);$online=!empty($_GET['pedido']);$id=(int)($_GET[$online?'pedido':'comanda']??0);
    if($test){$record=['branch_id'=>physical_branch_v14($app,$tenant)['id']??0,'label'=>'PRUEBA DE COMANDAS','notes'=>'Pedido de prueba. No preparar.'];$items=[['id'=>1,'product_name'=>'Hamburguesa','quantity'=>1,'notes'=>'Sin cebolla','options_json'=>'[{"group_name":"Extra","name":"Queso"}]','printer_target'=>'kitchen'],['id'=>2,'product_name'=>'Café frío','quantity'=>2,'notes'=>'Sin azúcar','options_json'=>'[]','printer_target'=>'bar']];}
    else{
        $record=$online?$app->one('SELECT o.*,o.order_number label FROM orders o WHERE o.id=? AND o.tenant_id=?',[$id,$tenant['id']]):$app->one('SELECT t.*,CONCAT(t.ticket_number," · ",COALESCE(r.name,t.sale_type),COALESCE(CONCAT(" · ",t.display_label),"")) label FROM pos_tickets t LEFT JOIN restaurant_tables r ON r.id=t.table_id WHERE t.id=? AND t.tenant_id=?',[$id,$tenant['id']]);
        if(!$record)throw new DomainException('Comanda no disponible para esta empresa.');
        $table=$online?'order_items':'pos_ticket_items';$fk=$online?'order_id':'ticket_id';
        $items=$app->all("SELECT i.*,COALESCE(c.printer_target,'kitchen') printer_target FROM $table i LEFT JOIN products p ON p.id=i.product_id LEFT JOIN categories c ON c.id=p.category_id WHERE i.$fk=?".($online?'':' AND i.kitchen_status<>"pending"').' ORDER BY i.id',[$id]);
    }
    $branch=$app->one('SELECT * FROM branches WHERE id=? AND tenant_id=?',[$record['branch_id'],$tenant['id']]);if(!$branch)throw new DomainException('Sucursal no disponible.');
    if(!$test&&!$online&&!empty($_GET['items'])){$selected=array_map('intval',explode(',',(string)$_GET['items']));$items=array_values(array_filter($items,fn($item)=>in_array((int)$item['id'],$selected,true)));}
    $groups=[];foreach($items as $item)$groups[$item['printer_target']][]=$item;
    admin_shell_start('Comandas · FISITAAP Print',$user,$tenant,'impresion');
    echo '<p>Comprueba cada PDF antes de preparar. Volver a enviar el mismo contenido recupera el PDF existente. Al enviar artículos nuevos desde la venta solo se incluyen esos artículos. Abrir desde cocina muestra la comanda completa.</p>';
    if($copy&&!$test)audit($app,(int)$tenant['id'],(int)$user['id'],'comanda_reprint',$online?'order':'pos_ticket',$id);echo '<form method="post">'.csrf_field().'<button class="btn" name="action" value="reprint_comanda">Reimprimir comanda</button></form>';
    foreach($groups as $target=>$lines){
        $text=[$tenant['name'],$branch['name'],'COMANDA · '.strtoupper($target),$record['label']];
        foreach($lines as $item){$text[]=$item['quantity'].' x '.$item['product_name'];foreach(json_decode((string)($item['options_json']??''),true)?:[] as $option)$text[]='  '.($option['group_name']??$option['group']??'Opción').': '.($option['name']??'');if(!empty($item['notes']))$text[]='  Nota: '.$item['notes'];}
        if(!empty($record['notes']))$text[]='Nota general: '.$record['notes'];$body=implode("\n",$text);
        $profile=printer_profile_148($branch,$target);$payload=['id'=>'tenant-'.$tenant['id'].'-'.($test?'test-'.bin2hex(random_bytes(8)):($online?'order-':'ticket-').$id).'-'.$target.'-'.substr(hash('sha256',$body),0,16).($copy?'-copy-'.bin2hex(random_bytes(8)):''),'document'=>$target,'width'=>$profile['width'],'printer'=>$profile,'text'=>$body];
        echo '<section class="card admin-card print-result-card"><h2>'.e(strtoupper($target)).'</h2><pre class="receipt-preview">'.e($body).'</pre><div class="alert" data-print-status></div><button class="btn" data-bridge-print>Enviar a FISITAAP Print</button><script type="application/json" data-print-payload>'.json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT).'</script><div data-print-job data-token="'.e((string)($branch['receipt_bridge_token']??'')).'" data-auto="'.(!empty($_GET['auto'])&&!empty($profile['autoprint'])?'1':'0').'"></div></section>';
    }
    if(!$groups)echo '<p>No hay artículos enviados a preparación.</p>';echo '<p><a class="btn btn-light" href="'.url($test?'admin/impresion':($online?'admin/pedidos?view='.$id:'admin/ventas?screen=order&ticket='.$id)).'">Volver</a></p>';admin_shell_end();
}
